setVal('user-name','Test Person'); setVal('user-email','test.person@example.com'); await wait(100);
let posts=0; const of=window.fetch; window.fetch=(...a)=>{ if((a[1]?.method)==='POST') posts++; return of(...a) };
document.querySelector('form button[type=submit]').click(); await wait(500);
