fs.querySelector('input[type=checkbox]').click(); await wait(300);
const afterSelect={error:document.getElementById('publisherAccess-error')?.textContent ?? null, describedby: fs.getAttribute('aria-describedby'), posts};
({afterSubmit, afterSelect})

