const wait=ms=>new Promise(r=>setTimeout(r,ms));
const fs=document.querySelector('form fieldset');
fs.querySelector('input[type=checkbox]').click(); await wait(300); // re-select Northwind Business
const inner=()=>[...fs.querySelectorAll('fieldset input')];
const edit=inner().find(c=>c.parentElement.textContent.trim()==='edit'); edit.click(); await wait(200);
const view=inner().find(c=>c.parentElement.textContent.includes('view'));
view.click(); await wait(200); // attempt to uncheck VIEW (disabled, should be a no-op)
const state=inner().map(c=>c.parentElement.textContent.trim()+':'+c.checked+(c.disabled?':disabled':''));
let sent=null; const of=window.fetch; window.fetch=async(u,i)=>{ if(i?.method==='POST'){ sent=JSON.parse(i.body); return new Response(JSON.stringify({name:'Test Person',attachedExisting:false}),{status:201}) } return of(u,i) };
document.querySelector('form button[type=submit]').click(); await wait(500);
window.fetch=of;
({state,sent})

